// Draws the Remote illustrations with the isometric kit and writes their path
// data as TypeScript modules. Run `node tools/remote-art/draw.mjs` after
// changing the geometry; the output files are not edited by hand.
import { writeFileSync } from 'node:fs';
import prettier from 'prettier';
import * as K from './isoKit.mjs';

const ROOT = new URL('../../', import.meta.url);
const HEADER =
  '// Generated by tools/remote-art/draw.mjs; edit the script and rerun it instead.\n';

const round = (value) => Math.round(value * 10) / 10;
const q = JSON.stringify;
const solid = (paths) => ({
  fill: paths.fill,
  shades: paths.shades,
  top: paths.top,
  crease: paths.crease ?? '',
  outline: paths.outline,
});
const solidTs = (s) =>
  `{ fill: ${q(s.fill)}, shades: ${q(s.shades)}, top: ${q(s.top)}, crease: ${q(s.crease)}, outline: ${q(s.outline)} }`;

async function write(relativePath, source) {
  const file = new URL(relativePath, ROOT);
  const options = (await prettier.resolveConfig(file.pathname)) ?? {};
  writeFileSync(file, await prettier.format(HEADER + source, { ...options, filepath: file.pathname }));
}

// A laptop: base slab, an upright lid, keyboard and trackpad outlines.
const base = { x: 0, y: 0, w: 92, d: 64, r: 5 };
const baseH = 4;
const lid = { x: 0, y: 0, w: 92, d: 3, r: 1.5 };
const lidZ = baseH;
const lidH = 60;

// The link: from a laptop screen point, over the lock, to the far screen.
const arc = (from, to, lift, steps = 24) =>
  Array.from({ length: steps + 1 }, (_, i) => {
    const t = i / steps;
    return [
      from[0] + (to[0] - from[0]) * t,
      from[1] + (to[1] - from[1]) * t,
      from[2] + (to[2] - from[2]) * t + Math.sin(Math.PI * t) * lift,
    ];
  });

// A padlock shackle: a half ring standing over the puck, facing the viewer.
function shackleOf(lock, P, facePath) {
  const top = lock.h;
  const points = [];
  const r = lock.r * 0.525;
  for (let i = 0; i <= 24; i++) {
    const t = Math.PI * (i / 24);
    const along = Math.cos(t) * r;
    points.push([lock.cx + along * 0.707, lock.cy - along * 0.707, top + 2 + Math.sin(t) * r * 1.3]);
  }
  const start = [points[0][0], points[0][1], top];
  const end = [points.at(-1)[0], points.at(-1)[1], top];
  return facePath([start, ...points, end], false);
}

function laptopOf(P) {
  const facePath = (points, closed = true) => K.pathOf(K.pointsAt(points, P), closed);
  const onScreen = (x0, x1, z0, z1, y = lid.d + 0.05) =>
    facePath([
      [x0, y, z0],
      [x1, y, z0],
      [x1, y, z1],
      [x0, y, z1],
    ]);
  const screenRule = (x0, x1, z, y = lid.d + 0.05) =>
    facePath(
      [
        [x0, y, z],
        [x1, y, z],
      ],
      false,
    );
  return {
    facePath,
    base: solid(K.slabOf(base, 0, baseH, P, 6, 0.6)),
    lid: solid(K.slabOf(lid, lidZ, lidH, P, 3)),
    halo: K.haloOf(base, 0, baseH, P),
    lines: {
      keyboard: K.planOutline({ x: 8, y: 9, w: 76, d: 26, r: 2 }, baseH, P, 3),
      trackpad: K.planOutline({ x: 32, y: 40, w: 28, d: 17, r: 2 }, baseH, P, 3),
      screen: onScreen(5, 87, lidZ + 6, lidZ + lidH - 5),
      // Rule lines that stand for a chat on the laptop.
      rules: [
        screenRule(12, 52, lidZ + 46),
        screenRule(12, 40, lidZ + 41),
        screenRule(32, 78, lidZ + 32),
        screenRule(44, 78, lidZ + 27),
        screenRule(12, 58, lidZ + 18),
      ].join(''),
      // A small approval card in the screen's lower right.
      card: onScreen(52, 82, lidZ + 9, lidZ + 22),
      cardRule: screenRule(56, 74, lidZ + 18),
      cardButton: onScreen(68, 79, lidZ + 11.5, lidZ + 14.5),
    },
  };
}

function lockOf(lock, P, facePath) {
  return {
    body: solid(K.cylinder(lock.cx, lock.cy, lock.r, 0, lock.h, P, 40, 0.5)),
    lines: {
      top: K.ring(lock.cx, lock.cy, lock.r - 2.2, lock.h, P, 40),
      shackle: shackleOf(lock, P, facePath),
      keyhole: K.ring(lock.cx, lock.cy, 1.2, lock.h, P, 16),
    },
  };
}

// The Remote journey: laptop, lock and a phone lying flat.
async function drawJourney() {
  const W = 280;
  const H = 168;
  const phone = { x: 146, y: 4, w: 32, d: 58, r: 6 };
  const phoneH = 4;
  const lock = { cx: 122, cy: 14, r: 8, h: 7 };
  const P = K.fitProjection(
    [
      ...K.boxCorners(base, 0, baseH),
      ...K.boxCorners(lid, lidZ, lidZ + lidH),
      ...K.boxCorners(phone, 0, phoneH),
      [lock.cx, lock.cy, 40],
    ],
    W,
    H,
    { pad: 14 },
  );
  const laptop = laptopOf(P);
  const padlock = lockOf(lock, P, laptop.facePath);
  const phoneScreen = K.insetPlan(phone, 3);
  const phoneLines = {
    screen: K.planOutline(phoneScreen, phoneH, P, 6),
    // Address field near the top of the phone screen.
    field: K.planOutline(
      { x: phone.x + 6, y: phone.y + 10, w: phone.w - 12, d: 6, r: 1.5 },
      phoneH,
      P,
      3,
    ),
    // Six code cells.
    cells: Array.from({ length: 6 }, (_, i) =>
      K.planOutline({ x: phone.x + 6 + i * 3.6, y: phone.y + 24, w: 2.8, d: 7, r: 0.6 }, phoneH, P, 2),
    ).join(''),
    rules: [
      K.lineOnTop([phone.x + 7, phone.y + 36], [phone.x + 25, phone.y + 36], phoneH, P),
      K.lineOnTop([phone.x + 7, phone.y + 41], [phone.x + 20, phone.y + 41], phoneH, P),
    ].join(''),
    button: K.planOutline(
      { x: phone.x + 6, y: phone.y + 47, w: phone.w - 12, d: 5, r: 1.5 },
      phoneH,
      P,
      3,
    ),
  };
  const linkFrom = [70, lid.d + 0.05, lidZ + 34];
  const linkMid = [lock.cx, lock.cy, lock.h + 9];
  const linkTo = [phone.x + phone.w / 2, phone.y + 20, phoneH + 0.05];
  const first = arc(linkFrom, linkMid, 10);
  const second = arc(linkMid, linkTo, 10);
  const facePath = laptop.facePath;

  await write(
    'src/features/remote/remoteArtPaths.ts',
    `// Isometric paths for RemoteArt (azimuth 45°, elevation 30°).

export interface SolidPaths {
  fill: string;
  shades: string[];
  top: string;
  crease: string;
  outline: string;
}

export const ART_WIDTH = ${W};
export const ART_HEIGHT = ${H};

export const HALO = ${q([laptop.halo, K.haloOf(phone, 0, phoneH, P)])};

export const LAPTOP_BASE: SolidPaths = ${solidTs(laptop.base)};
export const LAPTOP_LID: SolidPaths = ${solidTs(laptop.lid)};
export const PHONE: SolidPaths = ${solidTs(solid(K.slabOf(phone, 0, phoneH, P, 8, 0.6)))};
export const LOCK: SolidPaths = ${solidTs(padlock.body)};

export const LAPTOP_LINES = ${q(laptop.lines)};

export const PHONE_LINES = ${q(phoneLines)};

export const LOCK_LINES = ${q(padlock.lines)};

export const LINK = {
  whole: ${q(facePath([...first, ...second.slice(1)], false))},
  toLock: ${q(facePath(first.slice(0, 18), false))},
  fromLock: ${q(facePath(second.slice(7), false))},
  /** Where the link meets the lock, in viewBox units. */
  joint: ${q(K.iso(linkMid, P).map(round))},
};
`,
  );
}

// The sidebar launch card: the laptop mirrored into a browser window that
// floats beside it, joined over the lock.
async function drawLaunch() {
  const W = 264;
  const H = 120;
  const browser = { x: 132, y: 30, w: 76, d: 3, r: 1.5 };
  const browserZ = 10;
  const browserH = 52;
  const face = browser.y + browser.d + 0.05;
  const lock = { cx: 112, cy: 44, r: 6.5, h: 5.5 };
  const P = K.fitProjection(
    [
      ...K.boxCorners(base, 0, baseH),
      ...K.boxCorners(lid, lidZ, lidZ + lidH),
      ...K.boxCorners(browser, browserZ, browserZ + browserH),
      [lock.cx, lock.cy, 22],
    ],
    W,
    H,
    { pad: 8 },
  );
  const laptop = laptopOf(P);
  const facePath = laptop.facePath;
  const padlock = lockOf(lock, P, facePath);
  const onBrowser = (x0, x1, z0, z1) =>
    facePath([
      [x0, face, z0],
      [x1, face, z0],
      [x1, face, z1],
      [x0, face, z1],
    ]);
  const browserRule = (x0, x1, z) =>
    facePath(
      [
        [x0, face, z],
        [x1, face, z],
      ],
      false,
    );
  const dot = (cx, z) =>
    facePath(
      Array.from({ length: 12 }, (_, i) => {
        const t = (i / 12) * Math.PI * 2;
        return [cx + Math.cos(t) * 1.1, face, z + Math.sin(t) * 1.1];
      }),
    );
  const left = browser.x + 5;
  const top = browserZ + browserH;
  // The same five chat rules as the laptop screen, scaled into the window,
  // so the two screens read as one conversation.
  const mirror = [
    [12, 52, 46],
    [12, 40, 41],
    [32, 78, 32],
    [44, 78, 27],
    [12, 58, 18],
  ].map(([x0, x1, z]) =>
    browserRule(left + (x0 - 5) * 0.8, left + (x1 - 5) * 0.8, browserZ + 4 + (z - 10) * 0.82),
  );

  const linkFrom = [70, lid.d + 0.05, lidZ + 34];
  const linkMid = [lock.cx, lock.cy, lock.h + 8];
  const linkTo = [browser.x + 24, face, browserZ + 24];
  const first = arc(linkFrom, linkMid, 8);
  const second = arc(linkMid, linkTo, 8);

  await write(
    'src/features/remote/remoteLaunchArtPaths.ts',
    `// Isometric paths for the Remote launch card (azimuth 45°, elevation 30°).
import type { SolidPaths } from './remoteArtPaths';

export const LAUNCH_WIDTH = ${W};
export const LAUNCH_HEIGHT = ${H};

export const LAUNCH_HALO = ${q([laptop.halo, K.haloOf({ ...browser, y: browser.y - 2, d: 7 }, 0, 0.5, P)])};

export const LAUNCH_LAPTOP_BASE: SolidPaths = ${solidTs(laptop.base)};
export const LAUNCH_LAPTOP_LID: SolidPaths = ${solidTs(laptop.lid)};
export const LAUNCH_BROWSER: SolidPaths = ${solidTs(solid(K.slabOf(browser, browserZ, browserH, P, 3)))};
export const LAUNCH_LOCK: SolidPaths = ${solidTs(padlock.body)};

export const LAUNCH_LAPTOP_LINES = ${q({
      keyboard: laptop.lines.keyboard,
      trackpad: laptop.lines.trackpad,
      screen: laptop.lines.screen,
      rules: laptop.lines.rules,
    })};

export const LAUNCH_BROWSER_LINES = ${q({
      screen: onBrowser(browser.x + 3, browser.x + browser.w - 3, browserZ + 3, top - 3),
      bar: browserRule(browser.x + 3, browser.x + browser.w - 3, top - 9),
      dots: [dot(left + 1, top - 6), dot(left + 5, top - 6), dot(left + 9, top - 6)].join(''),
      address: onBrowser(left + 16, browser.x + browser.w - 8, top - 7.5, top - 4.5),
    })};

/** The browser's chat rules, in reading order, so they can appear one by one. */
export const LAUNCH_MIRROR_RULES = ${q(mirror)};

export const LAUNCH_LOCK_LINES = ${q(padlock.lines)};

/** Laptop screen to browser screen, passing over the lock. */
export const LAUNCH_LINK = ${q(facePath([...first, ...second.slice(1)], false))};
`,
  );
}

await drawJourney();
await drawLaunch();
